<?php use App\Core\View;ob_start(); ?><h1>Contatos</h1><div class="card"><form action="/contatos/importar" method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=$csrf?>"><label>Cole os e-mails<input name="emails" placeholder="ana@exemplo.com, bruno@exemplo.com"></label><label>ou envie TXT, CSV, DOC, DOCX, XLS, XLSX ou PDF (máx. 5 MB)<input name="file" type="file" accept=".txt,.csv,.doc,.docx,.xls,.xlsx,.pdf"></label><button class="btn">Importar</button></form></div><form method="get"><input name="q" value="<?=View::e($_GET['q']??'')?>" placeholder="Buscar por e-mail"><button>Buscar</button></form><p><?=$data['total']?> contato(s)</p><table><tr><th>E-mail</th><th>Origem</th><th>Status</th><th></th></tr><?php foreach($data['rows'] as $x): ?><tr><td><?=View::e($x['email'])?></td><td><?=View::e($x['source'])?></td><td><?=View::e($x['status'])?></td><td><form action="/contatos/excluir" method="post"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$x['id']?>"><button>Excluir</button></form></td></tr><?php endforeach ?></table><?php $body=ob_get_clean();$title='Contatos';require __DIR__.'/layout.php'; ?>
